SELECT set_config('team_test.start',((now() AT TIME ZONE 'Africa/Lagos')::date+2)::text||'T09:00:00+01:00',true);
RESET ROLE;
CREATE FUNCTION public.team_test_assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',message; END IF; RAISE NOTICE 'PASS: %',message; END $$;
CREATE FUNCTION public.team_test_reject(statement text,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS: %',message; RETURN; END; RAISE EXCEPTION 'FAIL: expected rejection: %',message; END $$;
INSERT INTO auth.users(id,email,raw_user_meta_data,email_confirmed_at) VALUES
 ('f8555555-5555-4555-8555-555555555555','team-manager@example.invalid','{}',now()),
 ('f8666666-6666-4666-8666-666666666666','team-coordinator@example.invalid','{}',NULL);
SELECT team_test_assert(NOT has_table_privilege('authenticated','provider_members','INSERT,UPDATE,DELETE'),'team membership has no direct client writes');
SELECT team_test_assert(NOT has_table_privilege('authenticated','provider_team_invitations','INSERT,UPDATE,DELETE'),'invitations have no direct client writes');
SELECT team_test_assert(NOT has_function_privilege('anon','respond_provider_team_invitation(uuid,integer,text)','EXECUTE'),'anonymous invitation acceptance denied');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f8333333-3333-4333-8333-333333333333',true);
SELECT team_test_reject($q$ SELECT invite_provider_team_member(current_setting('team_test.org')::uuid,'unknown@example.invalid','manager') $q$,'nonowner cannot invite members');
SELECT set_config('request.jwt.claim.sub','f8111111-1111-4111-8111-111111111111',true);
SELECT team_test_reject($q$ SELECT invite_provider_team_member(current_setting('team_test.org')::uuid,'team-manager@example.invalid','owner') $q$,'owner cannot delegate ownership through an invitation');
SELECT set_config('team_test.manager_invite',invite_provider_team_member(current_setting('team_test.org')::uuid,' TEAM-MANAGER@example.invalid ','manager')::text,true);
SELECT set_config('team_test.staff_invite',invite_provider_team_member(current_setting('team_test.org')::uuid,'team-coordinator@example.invalid','staff')::text,true);
SELECT team_test_assert((SELECT invited_email='team-manager@example.invalid' AND expires_at>now()+interval '6 days' FROM provider_team_invitations WHERE id=current_setting('team_test.manager_invite')::uuid),'invite normalizes email and has a server expiry');
SELECT team_test_assert(invite_provider_team_member(current_setting('team_test.org')::uuid,'prospective-user@example.invalid','staff') IS NOT NULL,'prospective users receive the same invitation result shape');
SELECT set_config('request.jwt.claim.sub','f8333333-3333-4333-8333-333333333333',true);
SELECT team_test_assert((SELECT count(*)=0 FROM provider_team_invitations),'unrelated user cannot enumerate team invitations');
SELECT team_test_reject($q$ SELECT respond_provider_team_invitation(current_setting('team_test.manager_invite')::uuid,1,'accept') $q$,'wrong recipient cannot accept a known invitation');
SELECT set_config('request.jwt.claim.sub','f8666666-6666-4666-8666-666666666666',true);
SELECT team_test_assert((SELECT count(*)=0 FROM list_provider_team_invitations()),'unverified email cannot list invitations');
SELECT team_test_reject($q$ SELECT respond_provider_team_invitation(current_setting('team_test.staff_invite')::uuid,1,'accept') $q$,'unverified email cannot accept invitations');
RESET ROLE;
UPDATE auth.users SET email_confirmed_at=now() WHERE id='f8666666-6666-4666-8666-666666666666';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f8555555-5555-4555-8555-555555555555',true);
SELECT team_test_assert((SELECT count(*)=1 FROM list_provider_team_invitations()),'verified recipient sees only its pending invitation');
SELECT respond_provider_team_invitation(current_setting('team_test.manager_invite')::uuid,1,'accept');
SELECT team_test_assert(respond_provider_team_invitation(current_setting('team_test.manager_invite')::uuid,1,'accept')=current_setting('team_test.org')::uuid,'acceptance retry does not duplicate or change membership');
SELECT team_test_assert(public.has_provider_team_access(current_setting('team_test.org')::uuid,'services'),'manager has service operations access');
SELECT team_test_assert(NOT public.owns_provider_workspace(current_setting('team_test.org')::uuid),'manager has not become the organization owner');
SELECT team_test_assert((SELECT count(*)=1 FROM list_provider_workspaces() WHERE id=current_setting('team_test.org')::uuid),'accepted team member can discover its workspace');
SELECT team_test_assert((SELECT count(*)=1 FROM provider_organizations WHERE id=current_setting('team_test.org')::uuid),'team member can read business profile');
SELECT team_test_assert((SELECT count(*)=0 FROM provider_documents WHERE provider_id=current_setting('team_test.org')::uuid),'manager cannot read verification documents');
SELECT team_test_assert((SELECT count(*)=0 FROM provider_verification_cases WHERE provider_id=current_setting('team_test.org')::uuid),'manager cannot inspect verification applications');
SELECT team_test_assert((SELECT count(*)=0 FROM storage.objects WHERE bucket_id='provider-credentials' AND split_part(name,'/',1)=current_setting('team_test.org')),'manager cannot read private credential files');
SELECT team_test_reject($q$ SELECT list_provider_team(current_setting('team_test.org')::uuid) $q$,'manager cannot enumerate the owner-only roster');
SELECT team_test_reject($q$ SELECT invite_provider_team_member(current_setting('team_test.org')::uuid,'other-staff@example.invalid','staff') $q$,'manager cannot invite or escalate other users');
SELECT team_test_reject($q$ SELECT submit_provider_verification(current_setting('team_test.org')::uuid) $q$,'manager cannot submit organization verification');
SELECT set_config('team_test.manager_service',save_provider_service(current_setting('team_test.org')::uuid,'{"name":"Manager service draft","description":"A manager-entered grooming service draft.","category":"grooming","delivery_mode":"clinic_visit","duration_minutes":30,"base_price":12000}')::text,true);
